337	// Submit 校验并接收一笔交易进入交易池。
338	// 拒绝时返回 *RejectError，可通过其 Reason 取得具体原因。
339	//
340	// 现有校验与拒绝原因优先于容量判断。同发送者同序号的合法加费替换不增加计数，
341	// 满池也可执行且不淘汰其他交易。全新交易在池满时只能从未被任何未决候选引用的
342	// 排队交易中挤出费用最低（同费取标识字典序最大）的一笔，且仅当新交易费用更高、
343	// 或费用相同且标识更小时成功；否则以 ReasonPoolFull 拒绝，池状态不变、不留历史。
344	func (n *Node) Submit(tx *Transaction) (*SubmitResult, error) {
345		if tx == nil {
346			return nil, errors.New("nil transaction")
347		}
348		n.mu.Lock()
349		defer n.mu.Unlock()
350	
351		cur := n.st
352		if tx.Sequence == 0 {
353			return nil, reject("sequence-must-be-positive", "sequence must be a positive integer")
354		}
355		if !tx.Verify() {
356			return nil, reject(ReasonBadSignature, "signature verification failed for sender %x", tx.Sender)
357		}
358		id := tx.ID()
359		// 同一标识的交易再次提交，一律视为重复（即使此前已确认、被替换、过期或被挤出）。
360		if _, ok := cur.Entries[id]; ok {
361			return nil, reject(ReasonDuplicate, "transaction %s already exists", id)
362		}
363		if cur.Round >= tx.Expiry {
364			return nil, reject(ReasonExpired, "expiry round %d is not greater than current round %d", tx.Expiry, cur.Round)
365		}
366		sender := tx.SenderHex()
367		if confirmed := cur.Accounts[sender]; tx.Sequence <= confirmed {
368			return nil, reject(ReasonOldSequence, "sequence %d is not greater than confirmed sequence %d", tx.Sequence, confirmed)
369		}
370		seqs := cur.Pool[sender]
371		isReplace := false
372		if seqs != nil {
373			if oldID, ok := seqs[tx.Sequence]; ok {
374				isReplace = true
375				old := cur.Entries[oldID]
376				if old.Status == stProposed {
377					return nil, reject(ReasonProposalLocked, "sequence %d is referenced by a pending candidate and cannot be replaced", tx.Sequence)
378				}
379				if tx.Fee <= old.Tx.Fee {
380					return nil, reject(ReasonLowFee, "new fee %d is not strictly higher than existing fee %d", tx.Fee, old.Tx.Fee)
381				}
382			}
383		}
384	
385		// 容量判断位于全部现有校验之后，且只针对新占位置的交易。
386		var evictID string
387		if !isReplace && cur.Capacity > 0 && cur.poolSize() >= cur.Capacity {
388			victim, ok := cur.evictionVictim()
389			if !ok {
390				return nil, reject(ReasonPoolFull,
391					"pool is full (%d/%d transactions) and no queued transaction is evictable", cur.poolSize(), cur.Capacity)
392			}
393			ve := cur.Entries[victim]
394			if tx.Fee < ve.Tx.Fee || (tx.Fee == ve.Tx.Fee && id > victim) {
395				return nil, reject(ReasonPoolFull,
396					"pool is full (%d/%d transactions): new transaction (fee %d) does not beat evictable transaction %s (fee %d)",
397					cur.poolSize(), cur.Capacity, tx.Fee, victim, ve.Tx.Fee)
398			}
399			evictID = victim
400		}
401	
402		// 校验通过后在副本上修改，落盘成功才替换内存，失败时确认前状态保持不变。
403		st := cur.clone()
404		result := &SubmitResult{TxID: id}
405		if oldID, ok := st.Pool[sender][tx.Sequence]; ok {
406			old := st.Entries[oldID]
407			old.Status = stReplaced
408			old.ReplacedBy = id
409			result.ReplacedID = oldID
410		} else if evictID != "" {
411			// 接收新交易与淘汰旧交易在同一个副本上一起生效、一起落盘。
412			v := st.Entries[evictID]
413			v.Status = stDropped
414			v.DropReason = DropReasonPoolCapacity
415			v.DropRound = st.Round
416			vsender := v.Tx.SenderHex()
417			delete(st.Pool[vsender], v.Tx.Sequence)
418			if len(st.Pool[vsender]) == 0 {
419				delete(st.Pool, vsender)
420			}
421			result.EvictedID = evictID
422		}
423	
424		txCopy := *tx
425		txCopy.Sender = append([]byte(nil), tx.Sender...)
426		txCopy.Content = append([]byte(nil), tx.Content...)
427		txCopy.Signature = append([]byte(nil), tx.Signature...)
428		st.Entries[id] = &poolEntry{Tx: &txCopy, Status: stQueued}
429		if st.Pool[sender] == nil {
430			st.Pool[sender] = map[uint64]string{}
431		}
432		st.Pool[sender][tx.Sequence] = id
433	
434		if err := n.save(st); err != nil {
435			return nil, err
436		}
437		n.st = st
438		return result, nil
439	}
440	
441	// poolSize 返回当前占位的交易数：排队与等待投票（被未决候选引用）的交易。
442	// 同一交易被多个候选引用只算一笔；已确认、被替换、已过期与被挤出的历史不占位置。
443	func (s *state) poolSize() uint64 {
444		var n uint64
445		for _, seqs := range s.Pool {
446			n += uint64(len(seqs))
447		}
448		return n
449	}
450	
451	// evictionVictim 选出满池时唯一可被淘汰的交易：未被任何未决候选引用的排队
452	// 交易中费用最低者，费用相同取交易标识字典序最大者。选择只取决于费用与标识，
453	// 与遍历顺序无关，结果确定。无可淘汰交易时第二个返回值为 false。
454	func (s *state) evictionVictim() (string, bool) {
455		var victim string
456		var victimFee uint64
457		found := false
458		for _, seqs := range s.Pool {
459			for _, id := range seqs {
460				e := s.Entries[id]
461				if e.Status != stQueued {
462					continue // 被未决候选引用的交易受保护
463				}
464				if !found || e.Tx.Fee < victimFee || (e.Tx.Fee == victimFee && id > victim) {
465					victim, victimFee, found = id, e.Tx.Fee, true
466				}
467			}
468		}
469		return victim, found
470	}
